result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/astar_det/astar.py", "content": """"Deterministic A* on a 10x10 grid.

Determinism guarantees:
  * Ties on f are broken by HIGHER g (deeper nodes first).
  * Remaining ties are broken by a monotonically increasing heapq entry
    counter, which makes insertion order (and hence pop order) fully
    deterministic even for identical priority tuples.
  * Neighbor generation order is fixed: up, left, right, down.
"""
import heapq
from collections import deque

# Fixed neighbor generation order.
MOVES = ((-1, 0), (0, -1), (0, 1), (1, 0))  # up, left, right, down

ROWS = 10
COLS = 10


def manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])


def neighbors(node, walls=frozenset(), rows=ROWS, cols=COLS):
    r, c = node
    for dr, dc in MOVES:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in walls:
            yield (nr, nc)


def astar(start, goal, walls=frozenset(), rows=ROWS, cols=COLS):
    """A* with f-ties broken by higher g, then by insertion counter.

    Returns the path as a list of (row, col) coordinates from start to goal.
    """
    counter = 0  # monotone tie-breaker for heap stability
    g_score = {start: 0}
    came_from = {}

    # Heap entries: (f, -g, counter, node). Min-heap pops lowest f,
    # then highest g (-g smallest), then earliest-inserted node.
    open_heap = [(manhattan(start, goal), 0, counter, start)]

    while open_heap:
        f, neg_g, _, current = heapq.heappop(open_heap)
        g = -neg_g
        if g > g_score.get(current, float("inf")):
            continue  # stale heap entry
        if current == goal:
            return _reconstruct(came_from, current)
        for nb in neighbors(current, walls, rows, cols):
            ng = g + 1
            if ng < g_score.get(nb, float("inf")):
                g_score[nb] = ng
                came_from[nb] = current
                counter += 1
                nf = ng + manhattan(nb, goal)
                heapq.heappush(open_heap, (nf, -ng, counter, nb))
    raise ValueError(f"no path from {start} to {goal}")


def _reconstruct(came_from, node):
    path = [node]
    while node in came_from:
        node = came_from[node]
        path.append(node)
    path.reverse()
    return path


def bfs_dist(start, goal, walls=frozenset(), rows=ROWS, cols=COLS):
    """Reference shortest-path length via BFS (unit edge weights)."""
    dist = {start: 0}
    q = deque([start])
    while q:
        cur = q.popleft()
        if cur == goal:
            return dist[cur]
        d = dist[cur] + 1
        for nb in neighbors(cur, walls, rows, cols):
            if nb not in dist:
                dist[nb] = d
                q.append(nb)
    return None
